use std::env;
use std::fs;
use std::process;

struct Report {
    count: i64,
    name: String,
    note: String,
}

fn parse_report(contents: &str) -> Result<Report, String> {
    let mut name: Option<String> = None;
    let mut count: Option<i64> = None;
    let mut note: Option<String> = None;
    for (line_number, raw_line) in contents.lines().enumerate() {
        let line = raw_line.strip_suffix('\r').unwrap_or(raw_line);
        let (field, value) = line
            .split_once('\t')
            .ok_or_else(|| format!("malformed field on line {}", line_number + 1))?;
        if field.is_empty() || value.contains('\t') {
            return Err(format!("malformed field on line {}", line_number + 1));
        }
        match field {
            "name" => {
                if name.is_some() {
                    return Err("duplicate field 'name'".to_string());
                }
                name = Some(value.to_string());
            }
            "count" => {
                if count.is_some() {
                    return Err("duplicate field 'count'".to_string());
                }
                count = Some(
                    value
                        .parse::<i64>()
                        .map_err(|_| format!("invalid count on line {}", line_number + 1))?,
                );
            }
            "note" => {
                if note.is_some() {
                    return Err("duplicate field 'note'".to_string());
                }
                note = Some(value.to_string());
            }
            other => return Err(format!("unknown field '{}'", other)),
        }
    }
    Ok(Report {
        count: count.ok_or_else(|| "missing field 'count'".to_string())?,
        name: name.ok_or_else(|| "missing field 'name'".to_string())?,
        note: note.ok_or_else(|| "missing field 'note'".to_string())?,
    })
}

fn escape_json(value: &str) -> String {
    let mut escaped = String::new();
    for ch in value.chars() {
        match ch {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            '\u{08}' => escaped.push_str("\\b"),
            '\u{0c}' => escaped.push_str("\\f"),
            ch if ch <= '\u{1f}' => {
                escaped.push_str(&format!("\\u{:04x}", ch as u32));
            }
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn run() -> Result<String, String> {
    let path = env::args()
        .nth(1)
        .ok_or_else(|| "missing report.tsv path".to_string())?;
    let contents = fs::read_to_string(&path)
        .map_err(|error| format!("cannot read '{}': {}", path, error))?;
    let report = parse_report(&contents)?;
    Ok(format!(
        "{{\"count\":{},\"name\":\"{}\",\"note\":\"{}\"}}\n",
        report.count,
        escape_json(&report.name),
        escape_json(&report.note)
    ))
}

fn main() {
    match run() {
        Ok(output) => print!("{}", output),
        Err(error) => {
            eprintln!("{}", error);
            process::exit(1);
        }
    }
}
